<script setup lang="ts">
import { computed, reactive, ref, watch } from 'vue'
import { Check, ChevronRight } from '@lucide/vue'
import AppDialog from '@/components/AppDialog.vue'
import type { Category } from '@/domain/models/category'
import { amountTextToCents, centsToAmountText, type TransactionFilters, type TransactionTypeFilter, type TransactionView } from './transaction-view'

const props = defineProps<{ open: boolean; view: TransactionView; categories: readonly Category[] }>()
const emit = defineEmits<{
  close: []
  apply: [filters: TransactionFilters]
}>()

const draft = reactive({
  transactionType: 'all' as TransactionTypeFilter,
  parentCategoryId: undefined as string | undefined,
  childCategoryIds: [] as string[],
  minAmount: '',
  maxAmount: '',
  noteKeyword: '',
  startDate: undefined as string | undefined,
  endDate: undefined as string | undefined,
})
const selectedParentId = ref<string | undefined>()
const categoryPickerOpen = ref(false)

const typeOptions: readonly { value: Exclude<TransactionTypeFilter, 'all'>; label: string }[] = [
  { value: 'expense', label: '支出' },
  { value: 'income', label: '收入' },
]
const typeOrder: Record<TransactionTypeFilter, number> = { all: 0, expense: 1, income: 2 }

const categoryById = computed(() => new Map(props.categories.map((category) => [category.id, category])))
const parentOptions = computed(() => props.categories
  .filter((category) => category.parentId === null && !category.disabled && (draft.transactionType === 'all' || category.type === draft.transactionType))
  .sort((a, b) => (typeOrder[a.type] - typeOrder[b.type]) || a.sortOrder - b.sortOrder))
const childOptions = computed(() => props.categories
  .filter((category) => {
    if (category.parentId === null || category.disabled) return false
    if (draft.transactionType !== 'all' && category.type !== draft.transactionType) return false
    if (selectedParentId.value && category.parentId !== selectedParentId.value) return false
    return true
  })
  .sort((a, b) => {
    const parentA = categoryById.value.get(a.parentId ?? '')
    const parentB = categoryById.value.get(b.parentId ?? '')
    return (typeOrder[a.type] - typeOrder[b.type])
      || (parentA?.sortOrder ?? 0) - (parentB?.sortOrder ?? 0)
      || a.sortOrder - b.sortOrder
  }))

const categoryLabel = computed(() => {
  const parent = draft.parentCategoryId ? categoryById.value.get(draft.parentCategoryId) : undefined
  const children = draft.childCategoryIds.map((id) => categoryById.value.get(id)).filter((category): category is Category => Boolean(category))
  if (parent && children.length) return `${parent.name} / ${children.map((child) => child.name).join('、')}`
  if (children.length) return children.map((child) => child.name).join('、')
  if (parent) return parent.name
  return '全部'
})

/** 时间范围（报表跳转带入）只展示不编辑，重置或确认后按用户操作保留/清除 */
const dateRangeLabel = computed(() => draft.startDate || draft.endDate
  ? `${draft.startDate ?? '…'} ～ ${draft.endDate ?? '…'}`
  : '全部')

function syncDraft(): void {
  const filters = props.view.filters
  draft.transactionType = filters.transactionType
  draft.parentCategoryId = filters.parentCategoryId
  draft.childCategoryIds = [...(filters.childCategoryIds ?? [])]
  draft.minAmount = centsToAmountText(filters.minAmountCents)
  draft.maxAmount = centsToAmountText(filters.maxAmountCents)
  draft.noteKeyword = filters.noteKeyword ?? ''
  draft.startDate = filters.startDate
  draft.endDate = filters.endDate
  selectedParentId.value = filters.parentCategoryId
}

watch(() => props.open, (open) => {
  if (open) syncDraft()
  else categoryPickerOpen.value = false
}, { immediate: true })

function toggleType(type: Exclude<TransactionTypeFilter, 'all'>): void {
  draft.transactionType = draft.transactionType === type ? 'all' : type

  if (draft.transactionType !== 'all') {
    const parent = draft.parentCategoryId ? categoryById.value.get(draft.parentCategoryId) : undefined
    if (parent?.type !== draft.transactionType) {
      draft.parentCategoryId = undefined
      selectedParentId.value = undefined
    }
    draft.childCategoryIds = draft.childCategoryIds.filter((childId) => categoryById.value.get(childId)?.type === draft.transactionType)
  }
}

function chooseParent(parentId: string | undefined): void {
  selectedParentId.value = parentId
  draft.parentCategoryId = parentId
  if (parentId) draft.childCategoryIds = draft.childCategoryIds.filter((childId) => categoryById.value.get(childId)?.parentId === parentId)
}

function chooseChild(childId: string | undefined): void {
  if (!childId) {
    draft.childCategoryIds = []
    return
  }
  if (draft.childCategoryIds.includes(childId)) draft.childCategoryIds = draft.childCategoryIds.filter((id) => id !== childId)
  else draft.childCategoryIds = [...draft.childCategoryIds, childId]
}

function applyFilters(): void {
  let minAmountCents = amountTextToCents(draft.minAmount)
  let maxAmountCents = amountTextToCents(draft.maxAmount)
  if (minAmountCents !== undefined && maxAmountCents !== undefined && minAmountCents > maxAmountCents) {
    const previousMin = minAmountCents
    minAmountCents = maxAmountCents
    maxAmountCents = previousMin
  }
  emit('apply', {
    transactionType: draft.transactionType,
    ...(draft.parentCategoryId ? { parentCategoryId: draft.parentCategoryId } : {}),
    ...(draft.childCategoryIds.length ? { childCategoryIds: [...draft.childCategoryIds] } : {}),
    ...(minAmountCents !== undefined ? { minAmountCents } : {}),
    ...(maxAmountCents !== undefined ? { maxAmountCents } : {}),
    ...(draft.noteKeyword.trim() ? { noteKeyword: draft.noteKeyword.trim() } : {}),
    ...(draft.startDate ? { startDate: draft.startDate } : {}),
    ...(draft.endDate ? { endDate: draft.endDate } : {}),
  })
  emit('close')
}

function resetFilters(): void {
  draft.transactionType = 'all'
  draft.parentCategoryId = undefined
  draft.childCategoryIds = []
  selectedParentId.value = undefined
  draft.minAmount = ''
  draft.maxAmount = ''
  draft.noteKeyword = ''
  draft.startDate = undefined
  draft.endDate = undefined
  categoryPickerOpen.value = false
}
</script>

<template>
  <Transition name="filter-panel-slide">
    <div v-if="open" class="filter-panel" role="dialog" aria-label="筛选流水">
      <div class="filter-form" aria-label="筛选条件">
        <div class="filter-form-row type-row">
          <span class="field-label">流水类型</span>
          <div class="type-options" role="group" aria-label="流水类型">
            <button
              v-for="option in typeOptions"
              :key="option.value"
              class="type-option"
              type="button"
              :aria-pressed="draft.transactionType === option.value"
              @click="toggleType(option.value)"
            >
              {{ option.label }}
            </button>
          </div>
        </div>

        <button class="filter-form-row filter-select-row" type="button" :aria-label="`分类，当前${categoryLabel}`" @click="categoryPickerOpen = true">
          <span class="field-label">分类</span>
          <span class="field-value" :class="{ 'is-placeholder': categoryLabel === '全部' }">{{ categoryLabel }}</span>
          <ChevronRight :size="18" aria-hidden="true" />
        </button>

        <div class="filter-form-row" aria-label="时间范围筛选，来自报表跳转">
          <span class="field-label">时间范围</span>
          <span class="field-value" :class="{ 'is-placeholder': dateRangeLabel === '全部' }">{{ dateRangeLabel }}</span>
        </div>

        <div class="filter-form-row amount-row">
          <span class="field-label">金额区间</span>
          <div class="amount-fields">
            <input v-model="draft.minAmount" aria-label="最小金额" type="number" min="0" step="0.01" inputmode="decimal" placeholder="最小金额" />
            <span class="amount-separator" aria-hidden="true">～</span>
            <input v-model="draft.maxAmount" aria-label="最大金额" type="number" min="0" step="0.01" inputmode="decimal" placeholder="最大金额" />
          </div>
        </div>

        <label class="filter-form-row note-row">
          <span class="field-label">备注</span>
          <input v-model="draft.noteKeyword" type="search" placeholder="输入备注关键词" />
        </label>
      </div>

      <div class="filter-actions">
        <button class="button secondary equal-action" type="button" @click="resetFilters">重置</button>
        <button class="button primary equal-action" type="button" @click="applyFilters">确认</button>
      </div>
    </div>
  </Transition>

  <AppDialog :open="categoryPickerOpen" title="选择分类" position="bottom" @close="categoryPickerOpen = false">
    <div class="category-cascade">
      <div class="category-column" role="listbox" aria-label="一级分类">
        <button class="category-option" type="button" role="option" :aria-selected="!selectedParentId" @click="chooseParent(undefined)">
          <span>全部</span>
          <Check v-if="!selectedParentId" :size="18" aria-hidden="true" />
        </button>
        <button
          v-for="parent in parentOptions"
          :key="parent.id"
          class="category-option"
          type="button"
          role="option"
          :aria-selected="selectedParentId === parent.id"
          @click="chooseParent(parent.id)"
        >
          <span>{{ parent.name }}</span>
          <Check v-if="selectedParentId === parent.id" :size="18" aria-hidden="true" />
        </button>
      </div>
      <div class="category-column is-child" role="listbox" aria-label="二级分类" aria-multiselectable="true">
        <button class="category-option" type="button" role="option" :aria-selected="!draft.childCategoryIds.length" @click="chooseChild(undefined)">
          <span>全部</span>
          <Check v-if="!draft.childCategoryIds.length" :size="18" aria-hidden="true" />
        </button>
        <button
          v-for="child in childOptions"
          :key="child.id"
          class="category-option"
          type="button"
          role="option"
          :aria-selected="draft.childCategoryIds.includes(child.id)"
          @click="chooseChild(child.id)"
        >
          <span>{{ child.name }}</span>
          <Check v-if="draft.childCategoryIds.includes(child.id)" :size="18" aria-hidden="true" />
        </button>
      </div>
    </div>
    <template #actions>
      <button class="button primary equal-action" type="button" @click="categoryPickerOpen = false">完成</button>
    </template>
  </AppDialog>
</template>

