import type { LocationQuery, LocationQueryRaw } from 'vue-router'
import type { TransactionRange } from '@/domain/services/date-range'
import type { LedgerType } from '@/domain/models/category'

export type TransactionDimension = 'time' | 'category'
export type CategoryGroupLevel = 'parent' | 'child'
export type TransactionTypeFilter = LedgerType | 'all'

export interface TransactionFilters {
  transactionType: TransactionTypeFilter
  parentCategoryId?: string
  childCategoryIds?: string[]
  minAmountCents?: number
  maxAmountCents?: number
  noteKeyword?: string
  /** 时间范围筛选（含两端，yyyy-MM-dd）。报表跳转带入，筛选面板可查看/清除 */
  startDate?: string
  endDate?: string
}

export interface TransactionView {
  dimension: TransactionDimension
  range: TransactionRange
  categoryLevel: CategoryGroupLevel
  filters: TransactionFilters
  focusCategoryId?: string
  focusType?: 'income' | 'expense'
}

const RANGES: readonly TransactionRange[] = ['day', 'week', 'month', 'year']
const TYPES: readonly TransactionTypeFilter[] = ['all', 'expense', 'income']
/** 本地日期键 yyyy-MM-dd（合法才接受，防止乱写 query 产生隐形过滤） */
const DATE_KEY_PATTERN = /^\d{4}-\d{2}-\d{2}$/

function firstValue(value: LocationQuery[string]): string | undefined {
  const single = Array.isArray(value) ? value[0] : value
  return single ?? undefined
}

function values(value: LocationQuery[string]): string[] {
  const raw = Array.isArray(value) ? value : value ? [value] : []
  return raw.filter((item): item is string => Boolean(item)).flatMap((item) => item.split(',')).map((item) => item.trim()).filter(Boolean)
}

export function amountTextToCents(value: string | number | undefined): number | undefined {
  const text = value === undefined ? undefined : String(value).trim()
  if (!text) return undefined
  const amount = Number(text)
  if (!Number.isFinite(amount) || amount < 0) return undefined
  return Math.round(amount * 100)
}

export function centsToAmountText(value: number | undefined): string {
  if (value === undefined) return ''
  return Number.isInteger(value / 100) ? String(value / 100) : (value / 100).toFixed(2).replace(/0+$/, '').replace(/\.$/, '')
}

function readFilters(query: LocationQuery): TransactionFilters {
  const rawType = firstValue(query.txType) as TransactionTypeFilter | undefined
  const transactionType = rawType && TYPES.includes(rawType) ? rawType : 'all'
  const parentCategoryId = firstValue(query.parent) || undefined
  const childCategoryIds = values(query.child)
  const noteKeyword = firstValue(query.note)?.trim() || undefined
  const minAmountCents = amountTextToCents(firstValue(query.min))
  const maxAmountCents = amountTextToCents(firstValue(query.max))
  const startDate = firstValue(query.from)
  const endDate = firstValue(query.to)
  const filters: TransactionFilters = { transactionType }
  if (parentCategoryId) filters.parentCategoryId = parentCategoryId
  if (childCategoryIds.length) filters.childCategoryIds = childCategoryIds
  if (minAmountCents !== undefined) filters.minAmountCents = minAmountCents
  if (maxAmountCents !== undefined) filters.maxAmountCents = maxAmountCents
  if (noteKeyword) filters.noteKeyword = noteKeyword
  if (startDate && DATE_KEY_PATTERN.test(startDate)) filters.startDate = startDate
  if (endDate && DATE_KEY_PATTERN.test(endDate)) filters.endDate = endDate
  return filters
}

function filterQuery(filters: TransactionFilters = { transactionType: 'all' }): LocationQueryRaw {
  return {
    ...(filters.transactionType !== 'all' ? { txType: filters.transactionType } : {}),
    ...(filters.parentCategoryId ? { parent: filters.parentCategoryId } : {}),
    ...(filters.childCategoryIds?.length ? { child: filters.childCategoryIds.join(',') } : {}),
    ...(filters.minAmountCents !== undefined ? { min: centsToAmountText(filters.minAmountCents) } : {}),
    ...(filters.maxAmountCents !== undefined ? { max: centsToAmountText(filters.maxAmountCents) } : {}),
    ...(filters.noteKeyword ? { note: filters.noteKeyword } : {}),
    ...(filters.startDate ? { from: filters.startDate } : {}),
    ...(filters.endDate ? { to: filters.endDate } : {}),
  }
}

/**
 * 从地址栏查询参数解析流水页视图。非法值一律回退到安全默认
 * （时间维度 / 月 / 一级分类），focus/type 只在分类维度下保留（报表跳转入口）。
 */
export function readTransactionView(query: LocationQuery): TransactionView {
  const rawRange = firstValue(query.range)
  const range: TransactionRange = RANGES.includes(rawRange as TransactionRange) ? rawRange as TransactionRange : 'month'
  const dimension: TransactionDimension = firstValue(query.dimension) === 'category' ? 'category' : 'time'
  const categoryLevel: CategoryGroupLevel = firstValue(query.level) === 'child' ? 'child' : 'parent'
  const view: TransactionView = { dimension, range, categoryLevel, filters: readFilters(query) }
  if (dimension === 'category') {
    const focus = firstValue(query.focus)
    const type = firstValue(query.type)
    if (focus) {
      view.focusCategoryId = focus
      if (type === 'income' || type === 'expense') view.focusType = type
    }
  }
  return view
}

/** 视图 → 地址栏查询参数。时间维度沿用旧版 range 参数；focus/type 随分类维度序列化。 */
export function transactionViewQuery(view: TransactionView): LocationQueryRaw {
  const filters = filterQuery(view.filters)
  if (view.dimension === 'category') {
    return {
      dimension: 'category',
      level: view.categoryLevel,
      ...filters,
      ...(view.focusCategoryId ? { focus: view.focusCategoryId } : {}),
      ...(view.focusCategoryId && view.focusType ? { type: view.focusType } : {}),
    }
  }
  return { range: view.range, ...filters }
}
