<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, onMounted, ref, watch, type ComponentPublicInstance } from 'vue'
import { ArrowUp, Check, ChevronDown, ChevronRight, Copy, Lock, Pencil, ReceiptText, Trash2 } from '@lucide/vue'
import { useRoute, useRouter } from 'vue-router'
import type { TransactionRange } from '@/domain/services/date-range'
import { dayGroupTitle, groupTitleOf, groupTitleSubtitleOf, localDateKey, WEEKDAY_LABELS } from '@/domain/services/date-range'
import { formatCents } from '@/domain/services/money'
import { groupTransactions, groupTransactionsByCategory, summarize } from '@/domain/services/statistics'
import { useAppStore } from '@/stores/app-store'
import CategoryIcon from '@/components/CategoryIcon.vue'
import { colorOf, softOf } from '@/domain/services/category-color'
import AppDialog from '@/components/AppDialog.vue'
import ConfirmGraphic from '@/components/ConfirmGraphic.vue'
import TransactionFilterSheet from './TransactionFilterSheet.vue'
import { readTransactionView, transactionViewQuery, type CategoryGroupLevel, type TransactionFilters } from './transaction-view'
import { consumeTransactionsScrollPosition } from '@/app/scroll-position'

const store = useAppStore()
const route = useRoute()
const router = useRouter()
// 视图状态唯一来源是地址栏（后退/前进/刷新/分享都可恢复）
const view = computed(() => readTransactionView(route.query))
// 报表分布行（支出分布/收入来源）点击进入的单分类明细模式：仅显示所选分类本期对应类型流水
const isReportCategoryDetail = computed(() => route.name === 'report-transactions' && (route.query.type === 'expense' || route.query.type === 'income'))
const filtersKey = computed(() => JSON.stringify(view.value.filters))
const viewKey = computed(() => `${view.value.dimension}|${view.value.dimension === 'time' ? view.value.range : view.value.categoryLevel}|${view.value.focusCategoryId ?? ''}|${filtersKey.value}`)
const expanded = ref(new Set<string>())
const initializedViewKey = ref<string>()
const activationOpen = ref(false)
const filterOpen = ref(false)
const viewPickerOpen = ref<'time' | 'category' | null>(null)
const openSwipeId = ref<string | null>(null)
const swipeOffset = ref(0)
const pendingDeleteId = ref<string>()
const pendingDeleteLabel = ref('')
const deleting = ref(false)
const didSwipe = ref(false)
const groupElements = new Map<string, HTMLElement>()
const SWIPE_REVEAL_PX = 228
const SWIPE_THRESHOLD_PX = 10
const SWIPE_CLOSE_THRESHOLD_PX = 10

type SwipeGesture = {
  id: string
  pointerId: number
  startX: number
  startY: number
  startOffset: number
  dragging: boolean
  cancelled: boolean
}
const swipeGesture = ref<SwipeGesture>()
const timeOptions: readonly { value: TransactionRange; label: string }[] = [
  { value: 'day', label: '天' },
  { value: 'week', label: '周' },
  { value: 'month', label: '月' },
  { value: 'year', label: '年' },
]
const categoryViewOptions: readonly { value: CategoryGroupLevel; label: string }[] = [
  { value: 'parent', label: '一级分类' },
  { value: 'child', label: '二级分类' },
]

const categories = computed(() => new Map(store.categories.map((category) => [category.id, category])))
const selectedReportCategory = computed(() => isReportCategoryDetail.value
  ? categories.value.get(view.value.focusCategoryId ?? '')
  : undefined)
const hasActiveFilters = computed(() => {
  const filters = view.value.filters
  return filters.transactionType !== 'all'
    || Boolean(filters.parentCategoryId)
    || Boolean(filters.childCategoryIds?.length)
    || filters.minAmountCents !== undefined
    || filters.maxAmountCents !== undefined
    || Boolean(filters.noteKeyword)
    || Boolean(filters.startDate)
    || Boolean(filters.endDate)
})
const filteredTransactions = computed(() => store.transactions.filter((record) => {
  const filters = view.value.filters
  const category = categories.value.get(record.categoryId)
  if (isReportCategoryDetail.value) {
    const focusId = view.value.focusCategoryId
    if (!focusId || selectedReportCategory.value?.type !== view.value.focusType || !filters.startDate || !filters.endDate) return false
    const recordDate = localDateKey(record.bookedAt)
    const belongsToCategory = view.value.categoryLevel === 'parent'
      ? record.categoryId === focusId || category?.parentId === focusId
      : record.categoryId === focusId
    return record.type === view.value.focusType && belongsToCategory && recordDate >= filters.startDate && recordDate <= filters.endDate
  }
  // 时间范围筛选（含两端，yyyy-MM-dd 字典序即日期序）；由报表跳转带入
  if (filters.startDate || filters.endDate) {
    const recordDate = localDateKey(record.bookedAt)
    if (filters.startDate && recordDate < filters.startDate) return false
    if (filters.endDate && recordDate > filters.endDate) return false
  }
  if (filters.transactionType !== 'all' && record.type !== filters.transactionType) return false
  if (filters.childCategoryIds?.length && !filters.childCategoryIds.includes(record.categoryId)) return false
  if (filters.parentCategoryId && record.categoryId !== filters.parentCategoryId && category?.parentId !== filters.parentCategoryId) return false
  if (filters.minAmountCents !== undefined && record.amountCents < filters.minAmountCents) return false
  if (filters.maxAmountCents !== undefined && record.amountCents > filters.maxAmountCents) return false
  if (filters.noteKeyword && !record.note.toLocaleLowerCase().includes(filters.noteKeyword.toLocaleLowerCase())) return false
  return true
}))
const displayGroups = computed(() => {
  if (isReportCategoryDetail.value) {
    const items = filteredTransactions.value
    return items.length ? [{
      key: 'report-category-detail',
      title: selectedReportCategory.value?.name ?? '分类流水',
      subtitle: '',
      icon: undefined,
      color: undefined,
      items,
      summary: summarize(items),
      focused: false,
    }] : []
  }
  if (view.value.dimension === 'category') {
    return groupTransactionsByCategory(filteredTransactions.value, store.categories, view.value.categoryLevel).map((group) => {
      const category = categories.value.get(group.categoryId)
      return {
        key: group.key,
        title: group.name,
        subtitle: `共 ${group.items.length} 笔`,
        icon: group.icon,
        color: category ? colorOf(category, store.categories) : '#1677ff',
        items: group.items,
        summary: summarize(group.items),
        focused: view.value.focusCategoryId === group.categoryId && (!view.value.focusType || view.value.focusType === group.type),
      }
    })
  }
  return [...groupTransactions(filteredTransactions.value, view.value.range)].map(([key, items]) => ({
    key,
    title: groupTitleOf(view.value.range, key),
    subtitle: groupTitleSubtitleOf(view.value.range, key),
    icon: undefined as string | undefined,
    color: undefined as string | undefined,
    items,
    summary: summarize(items),
    focused: false,
  }))
})
const focusName = computed(() => view.value.focusCategoryId ? categories.value.get(view.value.focusCategoryId)?.name ?? '未分类' : '')

function setGroupElement(key: string, element: Element | ComponentPublicInstance | null): void {
  if (element instanceof HTMLElement) groupElements.set(key, element)
  else groupElements.delete(key)
}

async function scrollFocusedGroupIntoView(): Promise<void> {
  await nextTick()
  const focused = displayGroups.value.find((group) => group.focused)
  const element = focused ? groupElements.get(focused.key) : undefined
  element?.scrollIntoView?.({ behavior: 'smooth', block: 'center' })
}

// 首次进入或切换视图后：聚焦组优先自动展开；时间维度展开第一组；分类维度默认全部收起；聚焦组滚到视口中央
watch([displayGroups, viewKey], ([groupsValue, key]) => {
  if (!groupsValue.length || initializedViewKey.value === key) return
  const focused = groupsValue.find((group) => group.focused)
  const initialKeys = focused ? [focused.key] : (view.value.dimension === 'category' ? [] : [groupsValue[0].key])
  expanded.value = new Set(initialKeys)
  initializedViewKey.value = key
  void scrollFocusedGroupIntoView()
}, { immediate: true })
watch(viewKey, () => { closeSwipe() })
// 普通聚焦视图的分类已删除时清掉聚焦；支出明细则保留参数并显示空状态，避免误露其他流水。
watch([() => view.value.focusCategoryId, () => store.initialized], ([focusId, initialized]) => {
  if (isReportCategoryDetail.value) return
  if (!focusId || !initialized) return
  if (categories.value.has(focusId)) return
  router.replace({ query: transactionViewQuery({ ...view.value, focusCategoryId: undefined, focusType: undefined }) })
}, { immediate: true })

// 时间/分类/筛选三个弹窗互斥：打开任意一个时关闭其他
function toggleViewPicker(picker: 'time' | 'category'): void {
  viewPickerOpen.value = viewPickerOpen.value === picker ? null : picker
  if (viewPickerOpen.value) filterOpen.value = false
}

function toggleFilter(): void {
  filterOpen.value = !filterOpen.value
  if (filterOpen.value) viewPickerOpen.value = null
}

function selectTimeRange(range: TransactionRange): void {
  viewPickerOpen.value = null
  void router.push({ query: transactionViewQuery({ ...view.value, dimension: 'time', range, focusCategoryId: undefined, focusType: undefined }) })
}

function selectCategoryView(level: CategoryGroupLevel): void {
  viewPickerOpen.value = null
  void router.push({ query: transactionViewQuery({ ...view.value, dimension: 'category', categoryLevel: level }) })
}

function applyFilters(filters: TransactionFilters): void {
  void router.push({ query: transactionViewQuery({ ...view.value, filters }) })
}

// 滚动超过两屏（进入第 3 屏）后显示回到顶部悬浮按钮
const showBackToTop = ref(false)
function onPageScroll(): void {
  showBackToTop.value = window.scrollY > window.innerHeight * 2
}
function backToTop(): void {
  window.scrollTo({ top: 0, behavior: 'smooth' })
}
onMounted(() => window.addEventListener('scroll', onPageScroll, { passive: true }))
onBeforeUnmount(() => window.removeEventListener('scroll', onPageScroll))

async function restoreRememberedScrollPosition(): Promise<void> {
  const scrollTop = consumeTransactionsScrollPosition()
  if (scrollTop === undefined) return

  // Router 的滚动处理在路由切换后很早就会执行；out-in 动画下列表尚未挂载，
  // WebView 会把目标位置截断成当时页面的最大高度。等列表真正渲染后再恢复。
  await nextTick()
  requestAnimationFrame(() => {
    window.scrollTo({ top: scrollTop, left: 0, behavior: 'auto' })
  })
}

function clearFocus(): void {
  void router.push({ query: transactionViewQuery({ ...view.value, focusCategoryId: undefined, focusType: undefined }) })
}

function closeSwipe(): void {
  openSwipeId.value = null
  swipeOffset.value = 0
  swipeGesture.value = undefined
}

function closeSwipeOnOutside(event: PointerEvent): void {
  const target = event.target as Element | null
  if (!target?.closest('.transaction-swipe-row')) closeSwipe()
}

function closeSwipeOnEscape(event: KeyboardEvent): void {
  if (event.key === 'Escape') closeSwipe()
}

function onSwipePointerDown(id: string, event: PointerEvent): void {
  if (event.pointerType === 'mouse' && event.button !== 0) return
  const target = event.target as Element | null
  if (target?.closest('.transaction-actions')) return
  const startOffset = openSwipeId.value === id ? swipeOffset.value : 0
  if (openSwipeId.value && openSwipeId.value !== id) closeSwipe()
  swipeGesture.value = {
    id,
    pointerId: event.pointerId,
    startX: event.clientX,
    startY: event.clientY,
    startOffset,
    dragging: false,
    cancelled: false,
  }
  didSwipe.value = false
}

function onSwipePointerMove(id: string, event: PointerEvent): void {
  if (!swipeGesture.value || swipeGesture.value.id !== id || swipeGesture.value.pointerId !== event.pointerId || swipeGesture.value.cancelled) return
  const deltaX = event.clientX - swipeGesture.value.startX
  const deltaY = event.clientY - swipeGesture.value.startY
  if (!swipeGesture.value.dragging) {
    if (Math.abs(deltaX) < 6 && Math.abs(deltaY) < 6) return
    if (Math.abs(deltaY) > Math.abs(deltaX)) {
      swipeGesture.value.cancelled = true
      return
    }
    swipeGesture.value.dragging = true
    const target = event.currentTarget as HTMLElement | null
    if (target && typeof target.setPointerCapture === 'function') target.setPointerCapture(event.pointerId)
  }
  event.preventDefault()
  const nextOffset = Math.max(-SWIPE_REVEAL_PX, Math.min(0, swipeGesture.value.startOffset + deltaX))
  openSwipeId.value = id
  swipeOffset.value = nextOffset
}

function onSwipePointerUp(id: string, event: PointerEvent): void {
  if (!swipeGesture.value || swipeGesture.value.id !== id || swipeGesture.value.pointerId !== event.pointerId) return
  const current = swipeGesture.value
  swipeGesture.value = undefined
  if (current.cancelled || !current.dragging) return
  event.preventDefault()
  const target = event.currentTarget as HTMLElement | null
  if (target && typeof target.releasePointerCapture === 'function' && target.hasPointerCapture?.(event.pointerId)) target.releasePointerCapture(event.pointerId)
  didSwipe.value = true
  const deltaX = event.clientX - current.startX
  // 已展开时按“向右拖动距离”关闭，不要求把整块内容拖回到边缘，轻推即可收起。
  const shouldClose = current.startOffset < 0 && deltaX >= SWIPE_CLOSE_THRESHOLD_PX
  const shouldOpen = !shouldClose && (current.startOffset < 0 || deltaX <= -SWIPE_THRESHOLD_PX)
  openSwipeId.value = shouldOpen ? id : null
  swipeOffset.value = shouldOpen ? -SWIPE_REVEAL_PX : 0
}

function onSwipePointerCancel(id: string, event: PointerEvent): void {
  if (!swipeGesture.value || swipeGesture.value.id !== id || swipeGesture.value.pointerId !== event.pointerId) return
  swipeGesture.value = undefined
  swipeOffset.value = openSwipeId.value === id ? -SWIPE_REVEAL_PX : 0
}

function onTransactionClick(id: string): void {
  if (didSwipe.value) {
    didSwipe.value = false
    return
  }
  if (openSwipeId.value === id) {
    closeSwipe()
    return
  }
  edit(id)
}

function actionLabel(item: typeof store.transactions[number]): string {
  return categories.value.get(item.categoryId)?.name ?? '未分类'
}

function copyTransaction(id: string): void {
  if (!store.canWrite) { closeSwipe(); activationOpen.value = true; return }
  closeSwipe()
  void router.push({ name: 'record-new', query: { copyFrom: id } })
}

function editTransaction(id: string): void {
  closeSwipe()
  edit(id)
}

function requestDelete(item: typeof store.transactions[number]): void {
  if (!store.canWrite) { closeSwipe(); activationOpen.value = true; return }
  pendingDeleteId.value = item.id
  pendingDeleteLabel.value = actionLabel(item)
}

function cancelDelete(): void {
  if (deleting.value) return
  pendingDeleteId.value = undefined
  pendingDeleteLabel.value = ''
}

async function confirmDelete(): Promise<void> {
  if (!pendingDeleteId.value || deleting.value || !store.canWrite) return
  deleting.value = true
  try {
    await store.repository.deleteTransaction(pendingDeleteId.value)
    await store.refresh()
    store.notify('流水已删除', 'success')
    closeSwipe()
  } catch (cause) {
    store.notify(cause instanceof Error ? cause.message : '删除失败，请重试', 'error')
  } finally {
    deleting.value = false
    pendingDeleteId.value = undefined
    pendingDeleteLabel.value = ''
  }
}

onMounted(() => {
  store.initialize()
  document.addEventListener('pointerdown', closeSwipeOnOutside)
  document.addEventListener('keydown', closeSwipeOnEscape)
  void restoreRememberedScrollPosition()
})
onBeforeUnmount(() => {
  document.removeEventListener('pointerdown', closeSwipeOnOutside)
  document.removeEventListener('keydown', closeSwipeOnEscape)
  closeSwipe()
})

function toggle(key: string): void {
  const next = new Set(expanded.value)
  next.has(key) ? next.delete(key) : next.add(key)
  expanded.value = next
}

function dayBuckets(items: typeof store.transactions): [string, typeof store.transactions][] {
  const buckets = new Map<string, typeof store.transactions>()
  for (const item of items) {
    const key = localDateKey(item.bookedAt)
    buckets.set(key, [...(buckets.get(key) ?? []), item])
  }
  return [...buckets]
}

/** 分类维度跨全部历史，日分桶标题必须带完整年月日，避免跨年份撞名 */
function dayHeaderTitle(day: string): string {
  if (view.value.dimension === 'time') return dayGroupTitle(view.value.range, day)
  const date = new Date(`${day}T00:00:00`)
  return `${date.getFullYear()}年${date.getMonth() + 1}月${date.getDate()}日 ${WEEKDAY_LABELS[date.getDay()]}`
}

function groupIconStyle(group: typeof displayGroups.value[number]): { background: string; color: string } {
  const color = group.color ?? '#1677ff'
  return { background: softOf(color), color }
}

function iconStyle(category: ReturnType<typeof categories.value.get> | undefined): { background: string; color: string } {
  const color = category ? colorOf(category, store.categories) : '#1677ff'
  return { background: softOf(color), color }
}

function edit(id: string): void {
  if (!store.canWrite) { activationOpen.value = true; return }
  router.push(`/record/${id}`)
}
</script>

<template>
  <main class="page transactions-page">
    <section v-if="!isReportCategoryDetail" class="view-bar card" aria-label="查看与筛选">
      <div class="view-trigger-row">
        <button class="view-trigger" type="button" :aria-pressed="view.dimension === 'time'" :aria-expanded="viewPickerOpen === 'time'" aria-label="时间" @click="toggleViewPicker('time')">
          <span>时间</span>
          <ChevronDown :size="16" aria-hidden="true" />
        </button>
        <button class="view-trigger" type="button" :aria-pressed="view.dimension === 'category'" :aria-expanded="viewPickerOpen === 'category'" aria-label="分类" @click="toggleViewPicker('category')">
          <span>分类</span>
          <ChevronDown :size="16" aria-hidden="true" />
        </button>
      </div>
      <span class="view-divider" aria-hidden="true"></span>
      <button class="filter-trigger" type="button" :class="{ 'is-active': hasActiveFilters }" aria-label="筛选流水" @click="toggleFilter">
        <svg class="filter-icon-svg" viewBox="0 0 1024 1024" aria-hidden="true">
          <path d="M548.8 959c-19.9 0-36-16.1-36-36V413.6c0-8.6 3.1-17 8.7-23.5l218-253h-565l200.8 254.2c5 6.4 7.8 14.2 7.8 22.3v312.6c0 19.9-16.1 36-36 36s-36-16.1-36-36V426.1L72 123.5c-8.6-10.8-10.2-25.6-4.2-38s18.6-20.3 32.4-20.3h717.9c14.1 0 26.9 8.2 32.7 21 5.9 12.8 3.7 27.8-5.5 38.5L584.8 427v496c0 19.9-16.1 36-36 36z" />
          <path d="M923.4 521.6H710.1c-19.9 0-36-16.1-36-36s16.1-36 36-36h213.3c19.9 0 36 16.1 36 36s-16.1 36-36 36zM923.4 704.4H710.1c-19.9 0-36-16.1-36-36s16.1-36 36-36h213.3c19.9 0 36 16.1 36 36s-16.1 36-36 36z" />
        </svg>
      </button>
      <Transition name="view-picker-slide">
        <div v-if="viewPickerOpen" class="view-picker-panel">
          <div v-if="viewPickerOpen === 'time'" class="view-picker-options" role="menu" aria-label="时间查看方式">
            <button
              v-for="option in timeOptions"
              :key="option.value"
              class="view-picker-option"
              type="button"
              role="menuitemradio"
              :aria-checked="view.dimension === 'time' && view.range === option.value"
              @click="selectTimeRange(option.value)"
            >
              <span>{{ option.label }}</span>
              <Check v-if="view.dimension === 'time' && view.range === option.value" :size="18" aria-hidden="true" />
            </button>
          </div>
          <div v-else class="view-picker-options" role="menu" aria-label="分类查看方式">
            <button
              v-for="option in categoryViewOptions"
              :key="option.value"
              class="view-picker-option"
              type="button"
              role="menuitemradio"
              :aria-checked="view.dimension === 'category' && view.categoryLevel === option.value"
              @click="selectCategoryView(option.value)"
            >
              <span>{{ option.label }}</span>
              <Check v-if="view.dimension === 'category' && view.categoryLevel === option.value" :size="18" aria-hidden="true" />
            </button>
          </div>
        </div>
      </Transition>
      <TransactionFilterSheet :open="filterOpen" :view="view" :categories="store.categories" @close="filterOpen = false" @apply="applyFilters" />
    </section>

    <Transition name="view-picker-fade">
      <div v-if="!isReportCategoryDetail && (viewPickerOpen || filterOpen)" class="view-picker-mask" aria-hidden="true" @click="viewPickerOpen = null; filterOpen = false"></div>
    </Transition>

    <div v-if="!isReportCategoryDetail && view.focusCategoryId" class="focus-banner card">
      <span class="focus-banner-text">已聚焦「{{ focusName }}」</span>
      <button class="focus-clear" type="button" @click="clearFocus">清除聚焦</button>
    </div>

    <section v-if="displayGroups.length === 0" class="empty card">
      <ReceiptText :size="44" aria-hidden="true" />
      <h2 v-if="isReportCategoryDetail">{{ selectedReportCategory ? '这段时间没有该分类的流水' : '该分类已不存在' }}</h2>
      <h2 v-else>{{ hasActiveFilters ? '没有符合条件的流水' : '还没有流水' }}</h2>
      <template v-if="!isReportCategoryDetail">
        <p>{{ hasActiveFilters ? '可以调整筛选条件后再查看。' : '点击下方“记一笔”记录第一笔收支。' }}</p>
        <button v-if="hasActiveFilters" class="button primary" type="button" @click="filterOpen = true">调整筛选</button>
        <RouterLink v-else class="button primary" to="/record">记一笔</RouterLink>
      </template>
    </section>

    <section v-for="group in displayGroups" :key="group.key" :ref="(element) => setGroupElement(group.key, element)" class="transaction-group card" :class="{ 'is-focused': group.focused, 'report-detail': isReportCategoryDetail }">
      <button v-if="!isReportCategoryDetail" class="group-header" type="button" :aria-expanded="expanded.has(group.key)" @click="toggle(group.key)">
        <span class="group-title">
          <component :is="expanded.has(group.key) ? ChevronDown : ChevronRight" :size="20" />
          <span v-if="group.icon" class="group-icon" :style="groupIconStyle(group)"><CategoryIcon :name="group.icon" /></span>
          <span class="group-title-stack">
            <span class="group-title-primary">{{ group.title }}</span>
            <span v-if="group.subtitle" class="group-title-secondary">{{ group.subtitle }}</span>
          </span>
          <span v-if="group.focused" class="focus-tag">聚焦</span>
        </span>
        <span class="group-summary"><span class="income">收 {{ formatCents(group.summary.incomeCents) }}</span><span class="expense">支 {{ formatCents(group.summary.expenseCents) }}</span></span>
      </button>
      <div v-if="isReportCategoryDetail || expanded.has(group.key)" class="group-content">
        <template v-for="[day, items] in dayBuckets(group.items)" :key="day">
          <div v-if="view.dimension === 'category' || view.range !== 'day'" class="day-header"><span>{{ dayHeaderTitle(day) }}</span><span>共 {{ items.length }} 笔</span></div>
          <div
            v-for="item in items"
            :key="item.id"
            class="transaction-swipe-row"
            :class="{ 'is-open': openSwipeId === item.id, 'is-dragging': swipeGesture?.id === item.id && swipeGesture.dragging }"
          >
            <div class="transaction-actions" :aria-label="`${actionLabel(item)}操作`">
              <button class="transaction-action copy" type="button" :aria-label="`复制 ${actionLabel(item)}`" @pointerdown.stop @click.stop="copyTransaction(item.id)">
                <Copy :size="18" aria-hidden="true" />
                <span>复制</span>
              </button>
              <button class="transaction-action edit" type="button" :aria-label="`编辑 ${actionLabel(item)}`" @pointerdown.stop @click.stop="editTransaction(item.id)">
                <Pencil :size="18" aria-hidden="true" />
